const w = $('1. Webhook (Contract Upload)').first();
const bin = w.binary || {};
const keys = Object.keys(bin);
const body = w.json.body || {};
if (keys.length > 0) {
  const b = bin[keys[0]];
  const name = String(b.fileName || '').toLowerCase();
  const mime = String(b.mimeType || '').toLowerCase();
  let inputType = 'unsupported';
  if (mime.includes('pdf') || name.endsWith('.pdf')) inputType = 'pdf';
  else if (mime.includes('wordprocessingml') || name.endsWith('.docx')) inputType = 'docx';
  else if (mime.startsWith('text/') || name.endsWith('.txt')) inputType = 'textfile';
  return [{ json: { inputType, fileName: b.fileName || '', text: '' }, binary: { data: b } }];
}
const text = String(body.text || body.contract || '');
return [{ json: { inputType: text.trim() ? 'text' : 'unsupported', fileName: '', text } }];

const text = String($json.text || '');
const body = $('1. Webhook (Contract Upload)').first().json.body || {};

const dictionary = {
  'العين المؤجرة': 'Leased Property / Leased Premises',
  'المؤجر': 'Lessor (First Party)',
  'مؤجر': 'Lessor (First Party)',
  'المستأجر': 'Lessee (Second Party)',
  'مستأجر': 'Lessee (Second Party)',
  'الطرف الأول': 'First Party',
  'الطرف الثاني': 'Second Party',
  'البائع': 'Seller',
  'المشتري': 'Buyer',
  'عقد إيجار': 'Lease Agreement',
  'عقد بيع سيارة': 'Motor Vehicle Sale Agreement',
  'القيمة الإيجارية': 'Rent',
  'رقم الشاسيه': 'Chassis Number',
  'رقم الشاسي': 'Chassis Number',
  'رقم المحرك': 'Engine Number',
  'الشرط الجزائي': 'Penalty Clause / Liquidated Damages',
  'المحكمة المختصة': 'Competent Egyptian Court',
  'فسخ العقد': 'Termination of the Contract',
  'جنيه مصري': 'Egyptian Pounds (EGP)',
  'عربون': 'Earnest Money',
  'مبلغ التأمين': 'Security Deposit',
  'مبلغ تأمين': 'Security Deposit'
};

const matched = [];
for (const [ar, en] of Object.entries(dictionary)) {
  if (text.includes(ar)) matched.push(ar + ' -> ' + en);
}
if (/القانون\s*رقم\s*\(?\s*4\s*\)?\s*لسنة\s*1996/.test(text)) matched.push('القانون رقم 4 لسنة 1996 -> Egyptian Law No. 4 of 1996 regarding Lease');

const arabicChars = (text.match(/[\u0600-\u06FF]/g) || []).length;
const latinChars = (text.match(/[A-Za-z]/g) || []).length;
const sourceLanguage = arabicChars >= latinChars ? 'Arabic' : 'English';
const requested = String(body.targetLanguage || body.targetLang || body.direction || '').toLowerCase();
let targetLanguage = sourceLanguage === 'Arabic' ? 'English' : 'Arabic';
if (requested.startsWith('ar') || requested.includes('إلى العربية') || requested.includes('الى العربية')) targetLanguage = 'Arabic';
if (requested.startsWith('en') || requested.includes('إلى الإنجليزية') || requested.includes('الى الانجليزية') || requested.includes('إلى الانجليزية')) targetLanguage = 'English';

if (!text.trim()) throw new Error('No text could be extracted from the input. Scanned (image-only) PDFs are not supported.');

return {
  json: {
    extractedText: text,
    sourceLanguage,
    targetLanguage,
    matchedDictionary: matched.join('\n') || 'No specific dictionary terms matched. Use standard Egyptian Civil Law terminology.'
  }
};

