const parts = ($json.content && Array.isArray($json.content.parts)) ? $json.content.parts : [];
const translation = String($json.mergedResponse || parts.map(p => p.text || '').join('') || $json.text || '').trim();
if (!translation) throw new Error('The AI model returned an empty translation.');

const targetLanguage = $('4. Egyptian Legal Dictionary Lookup').item.json.targetLanguage;
const dir = targetLanguage === 'Arabic' ? 'rtl' : 'ltr';
const lang = targetLanguage === 'Arabic' ? 'ar' : 'en';
const escaped = translation.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const html = '<!DOCTYPE html>\n<html lang="' + lang + '" dir="' + dir + '">\n<head>\n<meta charset="utf-8">\n<style>\n'
  + "body { font-family: 'Times New Roman', Arial, sans-serif; margin: 40px; line-height: 1.6; color: #111; }\n"
  + '.contract-body { white-space: pre-wrap; font-size: 14pt; text-align: justify; }\n'
  + '</style>\n</head>\n<body>\n<div class="contract-body">' + escaped + '</div>\n</body>\n</html>';

return { json: { translatedText: translation, targetLanguage, html } };

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary || {};
  const keys = Object.keys(bin);
  let key = keys.find(k => bin[k].fileName === 'document.xml' && String(bin[k].directory || '').includes('word'));
  if (!key) key = keys.find(k => bin[k].fileName === 'document.xml');
  if (!key) throw new Error('Could not find word/document.xml inside the uploaded DOCX file.');
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const xml = buffer.toString('utf8');
  const text = xml
    .replace(/<w:tab\/>/g, '\t')
    .replace(/<w:br[^>]*\/>/g, '\n')
    .replace(/<\/w:p>/g, '\n\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  out.push({ json: { text } });
}
return out;

const f = $input.first().json;
const source = String($('4. Egyptian Legal Dictionary Lookup').first().json.extractedText || '');
const translated = String(f.translatedText || '');

const toLatin = (s) => String(s)
  .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
  .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0));
const nums = (s) => (toLatin(s).replace(/(\d)[,\u066C](?=\d{3})/g, '$1').match(/\d+/g) || []);
const vins = (s) => (toLatin(s).toUpperCase().match(/\b[A-HJ-NPR-Z0-9]{17}\b/g) || []);

const sN = nums(source), tN = nums(translated);
const missingNumbers = [...new Set(sN.filter(n => !tN.includes(n)))];
const unexpectedNumbers = [...new Set(tN.filter(n => n.length >= 3 && !sN.includes(n)))];
const sV = vins(source), tV = vins(translated);
const missingVINs = [...new Set(sV.filter(v => !tV.includes(v)))];

const split = (s) => s.split(/\n\s*\n+/).filter(c => c.trim().length > 0);
const sc = split(source), tc = split(translated);
const alignedClauses = [];
for (let i = 0; i < Math.max(sc.length, tc.length); i++) {
  alignedClauses.push({
    clauseIndex: i + 1,
    sourceClause: sc[i] || '',
    translatedClause: tc[i] || '',
    status: (sc[i] && tc[i]) ? 'Aligned' : 'Mismatch Check Required'
  });
}

const isValid = missingNumbers.length === 0 && missingVINs.length === 0;
const needsWarning = !isValid || unexpectedNumbers.length > 0;
let html = f.html;
if (needsWarning) {
  const ar = f.targetLanguage === 'Arabic';
  const parts = [];
  if (missingNumbers.length) parts.push((ar ? 'أرقام من الأصل غير موجودة في الترجمة: ' : 'Numbers from the source not found in the translation: ') + missingNumbers.join(', '));
  if (missingVINs.length) parts.push((ar ? 'أرقام شاسيه/هيكل غير موجودة: ' : 'Chassis/VIN numbers not found: ') + missingVINs.join(', '));
  if (unexpectedNumbers.length) parts.push((ar ? 'أرقام في الترجمة غير موجودة في الأصل: ' : 'Numbers in the translation not found in the source: ') + unexpectedNumbers.join(', '));
  const banner = '<div style="background:#fef3c7;border:1px solid #f59e0b;padding:10px 14px;margin-bottom:16px;font-family:Arial,sans-serif;font-size:12pt">' +
    (ar ? '⚠ راجع هذه الأرقام يدويًا قبل الاعتماد: ' : '⚠ Please verify manually before relying on this translation: ') + parts.join(' | ') + '</div>';
  html = html.replace('<body>\n', '<body>\n' + banner + '\n');
}

return [{ json: {
  translatedText: translated,
  targetLanguage: f.targetLanguage,
  html,
  validation: { isValid, missingNumbers, unexpectedNumbers, missingVINs, totalSourceNumbers: sN.length, totalTranslatedNumbers: tN.length },
  alignedClauses,
  clauseCountMatches: sc.length === tc.length
} }];

const j = $json || {};
const candidates = [j.text, j.output, j.response, j.result, j.content, j.answer, j.mergedResponse];
let text = candidates.find(v => typeof v === 'string' && v.trim()) || '';
if (!text && Array.isArray(j.content)) text = j.content.map(p => p.text || '').join('');
if (!text && j.content && Array.isArray(j.content.parts)) text = j.content.parts.map(p => p.text || '').join('');
if (!text && typeof j === 'object') {
  const nested = Object.values(j).find(v => typeof v === 'object' && v && typeof v.text === 'string');
  if (nested) text = nested.text;
}
text = String(text || '').trim();
if (!text) throw new Error('OCR did not return any text. Make sure the PDF contains readable pages and the Gemini credential is connected.');
return { json: { inputType: 'pdf-ocr', fileName: $('1. Webhook (Contract Upload)').first().json.body?.fileName || '', text } };
